### Кедр {#kedr}

Системный кластер [Кедр](./kedr/overview.md) под управлением ПК СВ "Брест".

В данной локации размещаются все системные сервисы, за исключением случаев, требующих доступа из Интернет.

## Делегирование зоны

Зона astracloud.ru приналежит Astracloud (Rusonyx). Зоны третьего уровня `xaas|acp` делегируются с DNS @ Rusonyx.

![img](./img/dns-delegation.png)

<details>

```
@startuml ./img/dns-delegation.png
!NEW_C4_STYLE = 1
'  the bugfix is deactivated with following statement
!NO_LAY_ROTATE = 1
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml

' Set component colors for better visibility in both light/dark themes
UpdateElementStyle("component", $bgColor="#000000ff", $fontColor="#ffffffff")


Boundary(DNSDelegation, "DNS", $type="Delegation") {

  System(DNSRusonyx, "DNS @ Rusonyx") {
    Container(BindRusonyx, "Bind") {
      Component(ZoneInt, "int.rusonyx.ru", "Zone")
      Component(ZoneExt, "astracloud.ru", "Zone")
    }
  }

  System(DNSAstraCloudPlatfrom, "Internal|External DNS @ ACP") {
    Container(PDNSExternalPrimary, "ns1.acp.astracloud.ru", "nameserver") {
      Component(ZoneExtACP, "xaas|acp.astracloud.ru", "Zone")
    }
    Container(PDNSExternalSecondary, "ns2.acp.astracloud.ru", "nameserver") {
      Component(ZoneExtACPClone, "xaas|acp.astracloud.ru", "Zone")
    }
  }

}

Rel(ZoneExt, ZoneExtACP, "Delegates xaas|acp.astracloud.ru")
Rel_L(ZoneExt, ZoneExtACPClone, "Delegates xaas|acp.astracloud.ru")

Rel(ZoneExtACP, ZoneExtACPClone, "axfr")

@enduml
```

</details>

